public class Main {
    static String rank(int n) {
        return switch (n) {
            case 0 -> "zero";
            case 1, 2 -> "low";
            default -> {
                String s = n > 5 ? "high" : "mid";
                yield s + ":" + n;
            }
        }
        ;
    }
    public static void main(String[] args) {
        var x = rank(4);
